<script setup lang="ts">
import {displayText} from '../api'
import {computed,onUnmounted,ref,watch} from 'vue'
import {api,label,time} from '../api'
import {executionTypes,executionStatuses,resourceTypes,executionActive,saveExecutionReport,useExecution,type ExecutionTask,type ExecutionResource,type ExecutionReport} from '../execution'
import Icon from './Icon.vue'
const props=defineProps<{task:ExecutionTask}>()
const emit=defineEmits<{close:[];'show-map':[task:ExecutionTask];'show-event':[id:string];'show-device':[id:string];'show-run':[id:string];'open-task':[task:ExecutionTask]}>()
const store=useExecution(),eligibleResources=ref<ExecutionResource[]>([]),resourceId=ref(''),busy=ref(false),error=ref(''),resourcesLoading=ref(false)
const report=ref<ExecutionReport|null>(null),reportOpen=ref(false),resourceError=ref('')
let generation=0,resourceGeneration=0
const chosenResource=computed(()=>eligibleResources.value.find(r=>r.id===resourceId.value))
const active=computed(()=>executionActive(props.task)),canCancel=computed(()=>props.task.status==='pending'||active.value)
const priorityName=computed(()=>({high:'高',medium:'中',low:'低'}[props.task.priority]))
async function loadResources(){const token=++resourceGeneration,id=props.task.id;resourcesLoading.value=true;resourceError.value='';try{const next=await api<ExecutionResource[]>(`/execution-resources?task_id=${encodeURIComponent(id)}`);if(token===resourceGeneration&&props.task.id===id)eligibleResources.value=next}catch(e){if(token===resourceGeneration)resourceError.value=(e as Error).message}finally{if(token===resourceGeneration)resourcesLoading.value=false}}
async function action(name:'assign'|'start'|'cancel'|'retry'){if(busy.value)return;const token=generation,id=props.task.id;busy.value=true;error.value='';try{const result=await api<ExecutionTask>(`/execution-tasks/${encodeURIComponent(id)}/${name}`,name==='assign'?{resource_id:resourceId.value}:{});store.upsert(result);void store.refresh();if(token!==generation)return;if(name==='retry'){emit('open-task',result)}else{resourceId.value=result.resource_id||'';await loadResources()}}catch(e){if(token===generation){error.value=(e as Error).message;void loadResources()}}finally{if(token===generation)busy.value=false}}
async function viewReport(){if(busy.value)return;const token=generation,id=props.task.id;busy.value=true;error.value='';try{const value=await api<ExecutionReport>(`/execution-tasks/${encodeURIComponent(id)}/report`);if(token===generation&&value.task_id===id){report.value=value;reportOpen.value=true}}catch(e){if(token===generation)error.value=(e as Error).message}finally{if(token===generation)busy.value=false}}
watch(()=>props.task.id,()=>{generation++;busy.value=false;error.value='';report.value=props.task.report;reportOpen.value=false;resourceId.value=props.task.resource_id||'';void loadResources()},{immediate:true})
watch([()=>props.task.status,()=>props.task.resource_id],()=>{resourceId.value=props.task.resource_id||'';void loadResources();if(props.task.report)report.value=props.task.report})
watch(()=>store.resources.value.map(resource=>`${resource.id}:${resource.status}:${resource.current_task_id}`).join('|'),()=>{if(props.task.status==='pending')void loadResources()})
onUnmounted(()=>{generation++;resourceGeneration++})
</script>
<template>
 <aside class="execution-detail" aria-label="执行任务详情">
  <header class="execution-detail-heading"><div><span class="eyebrow">EXECUTION DETAIL · 模拟</span><h3>{{task.code}} · {{displayText(task.title)}}</h3></div><button class="icon-button" aria-label="关闭执行任务详情" @click="emit('close')"><Icon name="close" :size="18"/></button></header>
  <div class="execution-detail-body">
   <div class="execution-task-state"><span class="execution-status" :class="task.status">{{executionStatuses[task.status]}}</span><span class="execution-priority" :class="task.priority">{{priorityName}}优先级</span><span>{{executionTypes[task.task_type]}}</span></div>
   <p class="execution-scope">{{displayText(task.source_label)}} · {{task.task_type==='remote_sensing'?'模拟区域核查，没有真实卫星影像。':'模拟调度与巡检，没有真实设备控制或现场采集。'}}</p>
   <div v-if="error||task.error" class="execution-error" role="alert">{{displayText(error||task.error)}}</div>
   <dl class="execution-facts"><div><dt>目标位置</dt><dd>{{displayText(task.target_building_name)}}</dd></div><div><dt>关联事件</dt><dd><button class="text-button" @click="emit('show-event',task.incident_id)">{{task.incident_code?task.incident_code+' · ':''}}{{displayText(task.incident_title)}} ↗</button></dd></div><div><dt>调度资源</dt><dd>{{task.resource_code||'尚未选择'}} · {{displayText(task.resource_name||'待分配')}}</dd></div><div><dt>任务进度</dt><dd>{{Math.round(task.progress)}}% · 第 {{task.attempt}} 次尝试</dd></div><div><dt>创建时间</dt><dd>{{time(task.created_at,true)}}</dd></div><div><dt>完成时间</dt><dd>{{time(task.finished_at,true)}}</dd></div></dl>
   <progress class="execution-progress" :value="task.progress" max="100" :aria-label="`${task.code}执行进度`"></progress>
   <div class="execution-step-list"><div v-for="(step,index) in task.steps" :key="step.id" :class="step.status"><span>{{step.status==='completed'?'✓':String(index+1).padStart(2,'0')}}</span><div><strong>{{displayText(step.title)}}</strong><small>{{label(step.status)}}{{step.finished_at?' · '+time(step.finished_at):''}}</small></div></div></div>
   <section v-if="task.status==='pending'" class="execution-resource-picker"><div class="execution-section-heading"><h4>选择协同资源</h4><button class="text-button" :disabled="resourcesLoading||busy" @click="loadResources">刷新可用状态</button></div><p v-if="resourceError" class="execution-error" role="alert">{{displayText(resourceError)}}</p><p v-if="resourcesLoading" class="execution-muted">正在核查资源可用性…</p><label v-for="resource in eligibleResources" :key="resource.id" class="execution-resource-option" :class="{unavailable:!resource.eligible,chosen:resourceId===resource.id}"><input v-model="resourceId" type="radio" name="execution-resource" :value="resource.id" :disabled="!resource.eligible||busy" :aria-label="`选择资源 ${resource.code}`"/><span><strong>{{resource.code}} · {{displayText(resource.name)}}</strong><small>{{resourceTypes[resource.type]}} · {{label(resource.status)}}{{resource.battery!==null?' · 电量 '+resource.battery+'%':''}}</small><small v-if="resource.reason">{{resource.reason}}</small><small v-if="resource.device_id">映射设备 {{resource.device_id}}</small><small v-else>仅模拟资源，未接入真实遥感</small></span></label><p v-if="!resourcesLoading&&!eligibleResources.length" class="execution-muted">没有可分配资源，请刷新重试。</p><div class="execution-action-row"><button class="outline-button" :disabled="busy||resourcesLoading||!chosenResource?.eligible||resourceId===task.resource_id" @click="action('assign')">保存资源选择</button><button class="primary-button" :disabled="busy||!task.resource_id||resourceId!==task.resource_id||resourcesLoading||!chosenResource?.eligible" @click="action('start')"><Icon name="send" :size="15"/>确认启动模拟任务</button></div><p class="execution-muted">先保存资源，再确认启动。服务端会再次核验资源占用和在线状态。</p></section>
   <div class="execution-action-row"><button v-if="task.image_id" class="outline-button" @click="emit('show-map',task)"><Icon name="map" :size="15"/>查看地图与路线</button><button v-if="canCancel" class="outline-button danger" :disabled="busy" @click="action('cancel')">取消本次任务</button><button v-if="['completed','failed','cancelled'].includes(task.status)" class="outline-button" :disabled="busy" @click="action('retry')"><Icon name="refresh" :size="14"/>新建重试任务</button><button v-if="task.status==='completed'" class="primary-button" :disabled="busy" @click="viewReport"><Icon name="file" :size="15"/>查看执行报告</button></div>
   <p v-if="busy" class="execution-muted" role="status">正在保存操作，请稍候…</p>
   <details class="execution-associations"><summary>关联来源与设备</summary><code>任务 {{task.id}}</code><code>事件 {{task.incident_id}}</code><code v-if="task.evidence_snapshot_id">证据快照 {{task.evidence_snapshot_id}}</code><button v-if="task.source_run_id" class="text-button" @click="emit('show-run',task.source_run_id)">返回来源规则核查 {{task.source_run_id}} ↗</button><code v-if="task.parent_task_id">重试来源 {{task.parent_task_id}}</code><div class="execution-device-links"><button v-for="id in task.device_ids" :key="id" class="text-button" @click="emit('show-device',id)">{{id}} ↗</button></div></details>
   <section class="execution-log"><div class="execution-section-heading"><h4>执行日志</h4><span>{{task.logs.length}} 条 · 后端保存</span></div><ol><li v-for="entry in task.logs" :key="entry.id"><time>{{time(entry.at)}}</time><span>{{displayText(entry.message)}}</span></li></ol><p v-if="!task.logs.length" class="execution-muted">尚无执行记录。</p></section>
   <section v-if="reportOpen&&report" class="execution-report" aria-label="模拟执行报告"><div class="execution-section-heading"><h4>{{displayText(report.title)}}</h4><button class="icon-button" aria-label="收起执行报告" @click="reportOpen=false"><Icon name="close" :size="16"/></button></div><span class="execution-status completed">模拟执行完成 · 待人工复核</span><p>{{displayText(report.summary)}}</p><h5>模拟巡检发现</h5><ul><li v-for="item in report.findings" :key="item">{{displayText(item)}}</li></ul><h5>后续建议</h5><ul><li v-for="item in report.recommendations" :key="item">{{displayText(item)}}</li></ul><h5>适用范围与限制</h5><ul><li v-for="item in report.limitations" :key="item">{{displayText(item)}}</li></ul><p class="execution-muted">{{displayText(report.scope)}}</p><code>{{report.id}} · {{report.resource_code}}</code><small>{{time(report.started_at,true)}} — {{time(report.finished_at,true)}}</small><button class="outline-button" @click="saveExecutionReport(report)"><Icon name="download" :size="14"/>下载此任务报告 JSON</button></section>
   <p class="execution-scope">模拟完成会保留原始事件及证据，风险是否解除仍需人工核实。</p>
  </div>
 </aside>
</template>
